class WeightIOAdapter:
    def __init__(self, transport):
        self.transport = transport

    async def read_chunk(self, shard_id, byte_range):
        return await self.transport.fetch(shard_id, byte_range)

    async def list_keys(self, manifest):
        # returns iterator of (key, offset, length) for kv-prefetch
        return manifest.iter_keys()
